<template>
  <section class="plugin-center">
    <header class="plugin-heading"><div><p class="eyebrow">SMARTOPS / EXTENSION LAB</p><h1>插件中心<span>让运维能力，自由组合。</span></h1><p class="intro">把连接、诊断、知识与模型组织成你的工作台。每一项能力，都有清晰的入口与依赖。</p></div><button class="primary-btn" @click="openImport"><Plus aria-hidden="true" />导入自定义插件</button></header>
    <div class="workspace-bar"><span><i />本地工作区</span><span><b>{{ catalog.length }}</b> 可用清单</span><span><b>{{ installedCount }}</b> 已添加</span><span><b>{{ enabledCount }}</b> 已启用入口</span></div>
    <ExtensionDemo kind="plugin" />
    <p v-if="error" class="feedback error" role="alert">{{ error }}</p><p v-if="notice" class="feedback" role="status">{{ notice }}</p>
    <div class="orbit-layout">
      <RadialOrbitalTimeline :items="orbitItems" :selected-id="selectedId" :related-ids="selected?.dependencies || []" @select="selectPlugin" />
      <aside v-if="selected" class="plugin-detail" aria-label="插件详情">
        <div class="detail-top"><span class="eyebrow">SELECTED CAPABILITY</span><span class="status-chip">{{ status(selected) }}</span></div>
        <div class="detail-icon"><component :is="icons[selected.icon] || Grid" aria-hidden="true" /></div><p class="plugin-category">{{ selected.category }} · v{{ selected.version }}</p><h2>{{ selected.name }}</h2><p class="description">{{ selected.description }}</p>
        <div class="capability-tags"><span v-for="tag in selected.capabilities" :key="tag">{{ tag }}</span></div>
        <div class="dependency-section"><h3>能力依赖 <span>{{ selected.dependencies.length }}</span></h3><p v-if="!selected.dependencies.length">独立入口，无前置插件。</p><button v-for="id in selected.dependencies" :key="id" class="dependency-link" @click="selectPlugin(id)">{{ nameFor(id) }}<span>{{ state.installed[id] ? '已启用' : '待启用' }} →</span></button></div>
        <p class="boundary"><InfoFilled aria-hidden="true" />{{ selected.boundary }}</p>
        <div class="detail-actions"><button v-if="!isInstalled(selected.id)" class="primary-btn" @click="act(selected.id, 'add')">添加到工作区</button><template v-else><RouterLink v-if="state.installed[selected.id]" class="primary-btn" :to="pluginEntries[selected.entry].path">打开功能 <ArrowRight aria-hidden="true" /></RouterLink><button class="secondary-btn" @click="act(selected.id, state.installed[selected.id] ? 'disable' : 'enable')">{{ state.installed[selected.id] ? '停用入口' : '启用入口' }}</button><button class="text-btn" @click="act(selected.id, 'remove')">移出工作区</button></template><button v-if="selected.source === 'custom' && !isInstalled(selected.id)" class="text-btn" @click="removeCustom">删除自定义清单</button></div>
        <p v-if="selected.sourceUrl" class="local-note" style="overflow-wrap:anywhere">来源：{{ selected.sourceUrl }}</p><small class="local-note">{{ selected.source === 'custom' ? '自定义清单' : 'SmartOps 内置入口' }} · 启停仅管理此工作区入口，不改变后端服务。</small>
      </aside>
    </div>
    <section class="catalog-section"><div class="catalog-heading"><div><p class="eyebrow">BUILD YOUR WORKSPACE</p><h2>探索运维能力</h2></div><label class="search-field"><Search aria-hidden="true" /><input v-model="query" aria-label="搜索插件" placeholder="搜索插件、能力或描述" /></label></div>
      <div class="catalog-filters"><div class="category-tabs" aria-label="插件分类"><button v-for="item in ['全部', ...pluginCategories]" :key="item" :aria-pressed="category === item" @click="category = item; page = 1">{{ item }}</button></div><label class="installed-filter"><input v-model="onlyInstalled" type="checkbox" />仅看已添加</label></div>
      <div v-if="!filtered.length" class="empty-state"><Grid aria-hidden="true" /><h3>没有匹配的插件</h3><p>试试其他关键词，或导入一个自定义功能清单。</p><button class="secondary-btn" @click="query = ''; category = '全部'; onlyInstalled = false">清除筛选</button></div>
      <div v-else class="plugin-grid"><article v-for="item in visiblePlugins" :key="item.id" class="plugin-card" :class="{ active: selectedId === item.id }"><div class="card-top"><component :is="icons[item.icon] || Grid" aria-hidden="true" /><span class="status-chip">{{ status(item) }}</span></div><button class="card-title" :aria-label="`查看${item.name}详情`" @click="selectPlugin(item.id)">{{ item.name }}<ArrowRight aria-hidden="true" /></button><p>{{ item.description }}</p><div class="card-meta"><span>{{ item.category }}</span><span>{{ item.source === 'custom' ? '自定义' : '内置' }} · {{ item.version }}</span></div><div class="card-actions"><button class="secondary-btn" @click="selectPlugin(item.id)">查看详情</button><button v-if="!isInstalled(item.id)" class="text-btn" :aria-label="`添加${item.name}`" @click="act(item.id, 'add')">＋ 添加</button><RouterLink v-else-if="state.installed[item.id]" :to="pluginEntries[item.entry].path">打开功能 ↗</RouterLink><button v-else class="text-btn" :aria-label="`启用${item.name}`" @click="act(item.id, 'enable')">启用入口</button></div></article></div>
      <div v-if="filtered.length > pageSize" class="pagination"><button class="secondary-btn" :disabled="page === 1" @click="page--">上一页</button><span>{{ page }} / {{ pages }}</span><button class="secondary-btn" :disabled="page === pages" @click="page++">下一页</button></div>
    </section>
    <section class="extension-note"><Grid aria-hidden="true" /><div><h2>从一个入口，到可扩展的能力集合。</h2><p>导入 JSON 清单，自定义名称、分类与依赖，复用已有功能入口。清单保存在当前浏览器；目前不安装 npm 包、不加载第三方代码、不接入远程插件市场。</p></div><button class="secondary-btn" @click="openImport">查看清单模板 <ArrowRight aria-hidden="true" /></button></section>
    <el-dialog v-model="importOpen" title="导入自定义插件清单" width="min(640px, calc(100vw - 32px))" :close-on-click-modal="false">
      <form class="import-form" @submit.prevent="importPlugin"><SourceLinkReader v-if="importOpen" kind="plugin" @loaded="loadPluginSource" /><p v-if="sourceUrl" class="manifest-ids">来源：{{ sourceUrl }}{{ sourceModified ? '（已手动修改）' : '' }}</p><p>将常用功能组合为自己的入口。仅导入声明信息，不执行清单中的代码。</p><label for="plugin-manifest">JSON 清单</label><textarea id="plugin-manifest" v-model="manifest" @input="sourceModified = true" spellcheck="false" rows="13" :aria-invalid="!!importError" aria-describedby="manifest-help" /><p id="manifest-help">入口标识：{{ Object.keys(pluginEntries).join('、') }}。依赖填写已有插件 ID。</p><p class="manifest-ids">当前插件 ID：{{ catalog.map(item => item.id).join('、') }}</p><p v-if="importError" class="error" role="alert">{{ importError }}</p><div class="import-actions"><button type="button" class="secondary-btn" @click="importOpen = false">取消</button><button type="submit" class="primary-btn">校验并导入</button></div></form>
    </el-dialog>
  </section>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import { ElMessageBox } from 'element-plus/es/components/message-box/index.mjs'
import { ArrowRight, Collection, Connection, Cpu, DataLine, DataAnalysis, Document, Grid, InfoFilled, Monitor, Plus, Search, View } from '@element-plus/icons-vue'
import SourceLinkReader from '../../components/ui/source-link-reader.vue'
import ExtensionDemo from '../../components/ui/extension-demo.vue'
import RadialOrbitalTimeline from '../../components/ui/radial-orbital-timeline.vue'
import { pluginCategories, pluginEntries } from '../../domain/plugins/catalog.ts'
import { PLUGIN_STORAGE_KEY, initialWorkspace, decodeWorkspace, catalogFor, changePlugin, importManifest } from '../../domain/plugins/workspace.ts'
const icons = { Collection, Connection, Cpu, DataLine, DataAnalysis, Document, Grid, Monitor, View }
const error = ref(''), notice = ref(''), state = ref(initialWorkspace())
try { state.value = decodeWorkspace(localStorage.getItem(PLUGIN_STORAGE_KEY)) } catch { error.value = '本地插件配置无法读取，已显示默认工作区；原保存内容未被覆盖。' }
const catalog = computed(() => catalogFor(state.value))
const selectedId = ref('ops-inspector'), selected = computed(() => catalog.value.find(item => item.id === selectedId.value))
const isInstalled = id => Object.prototype.hasOwnProperty.call(state.value.installed, id)
const status = item => !isInstalled(item.id) ? '未添加' : state.value.installed[item.id] ? '入口已启用' : '入口已停用'
const nameFor = id => catalog.value.find(item => item.id === id)?.name || id
const installedCount = computed(() => Object.keys(state.value.installed).length)
const enabledCount = computed(() => Object.values(state.value.installed).filter(Boolean).length)
const orbitItems = computed(() => {
  const base = catalog.value.slice(0, 6)
  if (selected.value && !base.some(item => item.id === selectedId.value)) base[base.length - 1] = selected.value
  return base.map(item => ({ ...item, installed: isInstalled(item.id), enabled: state.value.installed[item.id] === true }))
})
const query = ref(''), category = ref('全部'), onlyInstalled = ref(false), page = ref(1), pageSize = 6
const filtered = computed(() => catalog.value.filter(item => (category.value === '全部' || item.category === category.value) && (!onlyInstalled.value || isInstalled(item.id)) && `${item.name} ${item.description} ${item.capabilities.join(' ')} ${item.id}`.toLowerCase().includes(query.value.trim().toLowerCase())))
const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize)))
const visiblePlugins = computed(() => filtered.value.slice((page.value - 1) * pageSize, page.value * pageSize))
watch([query, onlyInstalled], () => { page.value = 1 })
watch(pages, value => { page.value = Math.min(page.value, value) })
function persist(next) { localStorage.setItem(PLUGIN_STORAGE_KEY, JSON.stringify(next)); state.value = next }
function selectPlugin(id) { selectedId.value = id; error.value = ''; notice.value = '' }
function act(id, action) {
  error.value = ''; notice.value = ''
  try { persist(changePlugin(state.value, id, action)); notice.value = `${nameFor(id)}：${{ add: '已添加并启用入口', enable: '入口已启用', disable: '入口已停用', remove: '已移出工作区' }[action]}。` }
  catch (err) { error.value = err.name === 'QuotaExceededError' ? '浏览器存储空间不足，未保存本次更改。' : err.message }
}
const sourceUrl = ref(''), sourceModified = ref(false)
function loadPluginSource(result) { manifest.value = result.content; sourceUrl.value = result.source; sourceModified.value = false; importError.value = '' }
const importOpen = ref(false), importError = ref(''), manifest = ref('')
function openImport() {
  sourceUrl.value = ''; sourceModified.value = false
  importError.value = ''
  manifest.value = JSON.stringify({ id: 'my-nginx-runbook', name: '我的 Nginx 排障入口', version: '1.0.0', description: '集中查看 Nginx 故障排查知识与证据清单。', category: '知识与记忆', entry: 'knowledge', dependencies: ['ops-knowledge'] }, null, 2)
  importOpen.value = true
}
function importPlugin() {
  importError.value = ''
  try { const next = importManifest(state.value, manifest.value, sourceUrl.value ? sourceUrl.value + (sourceModified.value ? ' [手动修改]' : '') : ''); persist(next); selectedId.value = next.custom.at(-1).id; importOpen.value = false; query.value = ''; category.value = '全部'; onlyInstalled.value = false; page.value = pages.value; notice.value = '清单已导入，可在详情中添加到工作区。'; error.value = '' }
  catch (err) { importError.value = err.name === 'QuotaExceededError' ? '浏览器存储空间不足，清单未保存。' : err.message }
}
async function removeCustom() {
  const id = selectedId.value
  try { await ElMessageBox.confirm('删除此自定义清单？现有功能和真实业务数据不受影响。', '删除清单', { confirmButtonText: '删除', cancelButtonText: '取消', type: 'warning' }); persist(changePlugin(state.value, id, 'delete')); selectedId.value = 'ops-knowledge'; notice.value = '自定义清单已删除。'; error.value = '' }
  catch (err) { if (err !== 'cancel' && err !== 'close') error.value = err.message || '删除失败。' }
}
</script>
